import{_ as a,o,c as e,a2 as r}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"单工具深度评测","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"tools/reviews.md","filePath":"tools/reviews.md","lastUpdated":1785729506000}'),d={name:"tools/reviews.md"};function s(l,t,i,n,h,p){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="单工具深度评测" tabindex="-1">单工具深度评测 <a class="header-anchor" href="#单工具深度评测" aria-label="Permalink to &quot;单工具深度评测&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">待补充</p><p>这一页是个索引。每试完一个工具，用 <a href="/templates/tool-review">工具评测模板</a> 写一篇，然后在下面的表格里加一行。</p></div><h2 id="为什么要自己评测" tabindex="-1">为什么要自己评测 <a class="header-anchor" href="#为什么要自己评测" aria-label="Permalink to &quot;为什么要自己评测&quot;">​</a></h2><p>网上的工具评测有两个通病：</p><ol><li><strong>只测「能不能做」，不测「做得稳不稳」</strong>。演示视频里那条惊艳的素材，可能是生成三十条挑出来的。</li><li><strong>不测你的具体场景</strong>。通用测评说&quot;人物生成很强&quot;，但你要的是&quot;亚洲面孔、中式厨房、手持产品&quot;，这才是决定能不能交付的东西。</li></ol><p>所以自己的评测记录，价值远高于任何第三方榜单。</p><h2 id="评测清单" tabindex="-1">评测清单 <a class="header-anchor" href="#评测清单" aria-label="Permalink to &quot;评测清单&quot;">​</a></h2><p>试用一个新工具时，固定跑这几项，才有横向可比性：</p><table tabindex="0"><thead><tr><th>维度</th><th>怎么测</th></tr></thead><tbody><tr><td><strong>提示词服从度</strong></td><td>写一条包含 5 个明确约束的 Prompt，数它执行了几条</td></tr><tr><td><strong>出片率</strong></td><td>同一条 Prompt 生成 10 次，数几条可用。这个数字比&quot;最好的那条有多好&quot;重要得多</td></tr><tr><td><strong>一致性</strong></td><td>同一参考图跑 5 个不同镜头，看主体是否保持</td></tr><tr><td><strong>短板暴露</strong></td><td>故意测它的弱项：手部、文字、快速运动、复杂场景</td></tr><tr><td><strong>速度与成本</strong></td><td>单次耗时、单次消耗，以及达到&quot;可交付&quot;所需的总消耗</td></tr><tr><td><strong>商用条款</strong></td><td>当前订阅档位是否允许商用，有无标识要求</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">出片率是最重要的指标</p><p>惊艳的单条素材说明不了什么。<strong>做一个 6 镜头的项目，需要生成多少条才能凑齐 6 条可用的</strong>——这个数字直接决定了项目成本和排期。</p></div><h2 id="评测记录" tabindex="-1">评测记录 <a class="header-anchor" href="#评测记录" aria-label="Permalink to &quot;评测记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>类别</th><th>评测日期</th><th>出片率</th><th>结论</th><th>详情</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h2 id="待评测清单" tabindex="-1">待评测清单 <a class="header-anchor" href="#待评测清单" aria-label="Permalink to &quot;待评测清单&quot;">​</a></h2><p>想到要试的工具先记在这里：</p><ul><li>[ ]</li><li>[ ]</li><li>[ ]</li></ul><hr><p>写一篇新评测 → <a href="/templates/tool-review">工具评测模板</a></p>',17)])])}const b=a(d,[["render",s]]);export{u as __pageData,b as default};
